public class RightAlignedStaircaseTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            check("staircase(3)", "  1\n 12\n123", RightAlignedStaircase.staircase(3));
            check("staircase(1)", "1", RightAlignedStaircase.staircase(1));
            check("staircase(0)", "", RightAlignedStaircase.staircase(0));
            check("staircase(-2)", "", RightAlignedStaircase.staircase(-2));
            check("staircase(5)", "    1\n   12\n  123\n 1234\n12345",
                    RightAlignedStaircase.staircase(5));
            check("staircase(12) line count", 12, RightAlignedStaircase.staircase(12).split("\n", -1).length);
            String twelve = RightAlignedStaircase.staircase(12);
            check("staircase(12) last line wraps digits", "123456789012",
                    twelve.substring(twelve.lastIndexOf('\n') + 1));
            check("no trailing newline", false, RightAlignedStaircase.staircase(4).endsWith("\n"));
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected exception: " + t);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

