public class RightAlignedStaircase {

    public static String staircase(int n) {
        StringBuilder out = new StringBuilder();
        for (int line = 1; line <= n; line++) {
            if (line > 1) {
                out.append("\n");
            }
            for (int pad = 0; pad < n - line; pad++) {
                out.append(' ');
            }
            for (int col = 1; col <= line; col++) {
                out.append((char) ('0' + col % 10));
            }
        }
        return out.toString();
    }
}
